import boto3

def extract_tables(payload, config=None):
    config = config or {}
    textract_client = boto3.client(
        "textract",
        aws_access_key_id=os.environ.get("AWS_ACCESS_KEY_ID"),
        aws_secret_access_key=os.environ.get("AWS_SECRET_ACCESS_KEY"),
        region_name=os.environ.get("AWS_REGION", "us-east-1"),
    )

    response = textract_client.analyze_document(
        Document={'Bytes': payload},
        FeatureTypes=['TABLES']
    )

    blocks = response['Blocks']
    block_map = {block['Id']: block for block in blocks}
    table_blocks = [block for block in blocks if block['BlockType'] == 'TABLE']

    extracted_tables = []
    for table in table_blocks:
        cell_ids = []
        for rel in table.get('Relationships', []):
            if rel['Type'] == 'CHILD':
                cell_ids.extend(rel['Ids'])

        cells = [block_map[cid] for cid in cell_ids if block_map[cid].get('BlockType') == 'CELL']

        if not cells:
            continue

        max_row = max(cell.get('RowIndex', 0) for cell in cells)
        max_col = max(cell.get('ColumnIndex', 0) for cell in cells)

        if max_row == 0 or max_col == 0:
            continue

        table_grid = [['' for _ in range(max_col)] for _ in range(max_row)]

        for cell in cells:
            row_idx = cell.get('RowIndex', 1) - 1
            col_idx = cell.get('ColumnIndex', 1) - 1

            if row_idx < 0 or col_idx < 0:
                continue

            cell_text = ""
            if 'Relationships' in cell:
                for rel in cell['Relationships']:
                    if rel['Type'] == 'CHILD':
                        for child_id in rel['Ids']:
                            child = block_map.get(child_id)
                            if child and child.get('BlockType') == 'WORD':
                                cell_text += child['Text'] + ' '

            table_grid[row_idx][col_idx] = cell_text.strip()

        extracted_tables.append(table_grid)
    result = extracted_tables
    return result
